/*
Theme Name: Philsoc (прототип)
Description: Тема сайту ГО «УТФО ім. М. Култаєвої». Салатова гама + рожеві акценти. Прототип.
Version: 0.3
*/

:root{
  /* Салатова шкала: основний колір #b6f6bb; відтінки розрізняють рівні та розділи */
  --g50:#f3fdf4;
  --g100:#e1fbe4;
  --g200:#b6f6bb;   /* основний */
  --g300:#8fe898;
  --g400:#63d06f;
  --g500:#41ad4e;
  --g600:#2f8a3b;
  --g700:#236b2e;
  --g800:#1a5224;
  --g900:#123a19;
  /* Рожеві акценти */
  --pink:#F85D96;
  --pink-dark:#d6336f;
  --pink-soft:#fde3ee;

  --bg:var(--g50);
  --paper:#ffffff;
  --ink:#16251a;
  --muted:#5d6e61;
  --line:#d3e8d6;
  --accent:var(--pink);
  --link:var(--g700);
  --serif:Georgia,"Times New Roman",serif;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
}
*{box-sizing:border-box}
html{font-size:17px}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--serif);line-height:1.65}
a{color:var(--link);text-decoration:none}
a:hover{color:var(--g900);text-decoration:underline}
img{max-width:100%;height:auto}
.wrap{max-width:1080px;margin:0 auto;padding:0 24px}

.proto-note{background:#eceeed;color:#4b5563;font:13px var(--sans);text-align:center;padding:6px 12px;border-bottom:1px solid #d9dcdb}

/* шапка */
.site-header{background:var(--paper)}
.head-row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-top:18px;padding-bottom:16px}
.brand{display:flex;align-items:center;gap:18px;color:var(--ink)}
.brand:hover{text-decoration:none;color:var(--ink)}
.brand-logo{height:84px;width:auto;flex:none;display:block}
.brand-text strong{display:block;font-size:1.4rem;font-weight:700;color:var(--g800);line-height:1.2}
.brand-text em{display:block;font-size:.82rem;color:var(--muted);font-style:normal;line-height:1.35;margin-top:3px}
@media (min-width:1100px){.brand-text em{white-space:nowrap}}
.lang{font:13px var(--sans);display:flex;gap:4px;flex:none}
.lang span,.lang a{padding:4px 10px;border:1px solid var(--line);border-radius:3px;color:var(--g700)}
.lang a:hover{background:var(--g100);border-color:var(--g300);color:var(--g900);text-decoration:none}
.lang span.on{background:var(--g200);border-color:var(--g300);color:var(--g900);font-weight:600}

/* головне меню: основний салатовий */
.main-nav{background:var(--g200);border-top:1px solid var(--g300);border-bottom:1px solid var(--g300)}
.main-nav ul,.journal-bar ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap}
.main-nav li{position:relative}
.main-nav a{display:block;padding:12px 18px;color:var(--g900);font:15px var(--sans);font-weight:500}
.main-nav a:hover{background:var(--g300);color:var(--g900);text-decoration:none}
.main-nav .current-menu-item>a,.main-nav .current-menu-ancestor>a{background:var(--g300)}
.main-nav .sub-menu,.journal-bar .sub-menu{display:none;position:absolute;left:0;top:100%;z-index:20;min-width:250px;background:var(--paper);border:1px solid var(--line);border-top:3px solid var(--g400);box-shadow:0 8px 20px rgba(18,58,25,.12);flex-direction:column}
.main-nav li:hover>.sub-menu,.journal-bar li:hover>.sub-menu{display:flex}
.main-nav .sub-menu a,.journal-bar .sub-menu a{color:var(--g900);padding:9px 16px;border-bottom:1px solid var(--line);background:transparent;box-shadow:none}
.main-nav .sub-menu a:hover,.journal-bar .sub-menu a:hover{background:var(--g100);color:var(--g900)}

/* розділ «Журнал»: насиченіший салатовий — інший рівень */
.journal-banner{background:var(--paper);border-bottom:1px solid var(--line);padding:22px 0 16px}
.journal-banner .kicker{font:700 12px var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--g800)}
.journal-banner h2{margin:4px 0 2px;font-size:1.65rem;color:var(--g900);font-weight:700}
.journal-banner p{margin:0;color:var(--g800);font-size:.9rem}
.journal-bar{background:var(--g100);border-bottom:1px solid var(--g300)}
.journal-bar a{display:block;padding:11px 16px;font:14px var(--sans);color:var(--g900)}
.journal-bar li{position:relative}
.journal-bar>.wrap>ul>li>a:hover{background:var(--g200);color:var(--g900);text-decoration:none}
.journal-bar .current-menu-item>a,.journal-bar .current-menu-ancestor>a{background:var(--g300);font-weight:600}
.journal-bar .menu-item-has-children>a::after{content:" ▾";font-size:.7em;color:var(--g600)}

/* контент */
.content{padding-top:40px;padding-bottom:60px}
.entry{max-width:760px;background:var(--paper);border:1px solid var(--line);border-top:4px solid var(--g300);padding:36px 44px}
.entry h1{margin:0 0 .6em;font-size:1.9rem;color:var(--g800);font-weight:700;line-height:1.25}
.entry h3{color:var(--g700)}
.entry-meta{font:13px var(--sans);color:var(--muted);margin-bottom:1.2em}
.entry-body p{margin:0 0 1em}
/* кнопки: темно-зелені, без рожевого */
.btn{display:inline-block;background:var(--g800);color:#fff;font:600 14px var(--sans);padding:10px 20px;border-radius:3px;border:1px solid var(--g800)}
.btn:hover{background:var(--g700);border-color:var(--g700);color:#fff;text-decoration:none}
.btn.ghost{background:transparent;color:var(--g800);border:1px solid var(--g800);box-shadow:none}
.btn.ghost:hover{background:var(--g200);color:var(--g900);border-color:var(--g800)}
.cite{background:var(--g50);border-left:3px solid var(--pink);padding:10px 16px;font-size:.9rem;margin-top:1.4em}

/* стаття */
.entry .authors{font-size:1.05rem;color:var(--g800);font-weight:600;margin:-.3em 0 .6em}
.refs{padding-left:1.2em;font-size:.92rem;color:#34493a}
.refs li{margin-bottom:.4em}

/* кроки подання */
.steps{counter-reset:s;list-style:none;margin:1.2em 0;padding:0}
.steps li{counter-increment:s;position:relative;padding:10px 0 10px 52px;border-bottom:1px solid var(--line)}
.steps li::before{content:counter(s);position:absolute;left:0;top:8px;width:34px;height:34px;border-radius:50%;background:var(--g200);color:var(--g900);font:700 15px/34px var(--sans);text-align:center;border:2px solid var(--pink)}

/* головна */
.hero{background:var(--paper);border-bottom:1px solid var(--line);padding:56px 0}
.hero .kicker{font:700 12px var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--g800)}
.hero h1{margin:.2em 0 .4em;font-size:2.4rem;color:var(--g900);font-weight:700;line-height:1.2;max-width:760px}
.hero p{max-width:640px;color:#27402c;font-size:1.05rem}
.grid{display:grid;grid-template-columns:2fr 1fr;gap:36px;padding:44px 0}
.section-title{font-size:1.15rem;color:var(--g800);border-bottom:2px solid var(--g300);padding-bottom:6px;margin:0 0 18px;font-weight:700;position:relative}
.section-title::after{content:"";position:absolute;left:0;bottom:-2px;width:64px;height:2px;background:var(--pink)}
.news-item{padding:0 0 16px;margin:0 0 16px;border-bottom:1px solid var(--line)}
.news-item time{font:12px var(--sans);color:var(--g600);text-transform:uppercase;letter-spacing:.06em;font-weight:600}
.news-item h3{margin:2px 0 4px;font-size:1.12rem;font-weight:600}
.news-item h3 a{color:var(--g900)}
.news-item h3 a:hover{color:var(--g700)}
.news-item p{margin:0;color:#34493a;font-size:.95rem}
.card{background:var(--paper);border:1px solid var(--line);border-top:4px solid var(--g300);padding:22px}
.card .cover{height:150px;background:linear-gradient(135deg,var(--g600),var(--g800));color:#fff;display:grid;place-items:center;font-size:1.05rem;text-align:center;padding:12px;margin-bottom:14px;border-bottom:4px solid var(--pink)}
.card h3{margin:0 0 4px;font-size:1.05rem;color:var(--g800)}
.card p{margin:0 0 12px;font-size:.92rem;color:var(--muted)}
.trio{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding-bottom:56px}
.trio .card:nth-child(1){border-top-color:var(--g200)}
.trio .card:nth-child(2){border-top-color:var(--g400)}
.trio .card:nth-child(3){border-top-color:var(--g600)}

/* списки */
.list-item{padding:18px 0;border-bottom:1px solid var(--line)}
.list-item h3{margin:0 0 4px;font-size:1.1rem;font-weight:600}
.list-item .by{font:13px var(--sans);color:var(--muted)}
.type-head{margin:2em 0 .4em;color:var(--g800);font-size:1.25rem;border-bottom:1px solid var(--g300);padding-bottom:4px}
.toc{list-style:none;margin:0;padding:0}
.toc li{padding:14px 0;border-bottom:1px solid var(--line)}
.toc .t{font-weight:600}
.toc a.t:hover{text-decoration:underline}
.toc .a{font:13px var(--sans);color:var(--muted)}

/* підвал */
.site-footer{background:var(--g900);color:#cfe6d3;font:14px var(--sans);padding:34px 0;margin-top:20px;border-top:4px solid var(--pink)}
.site-footer a{color:var(--g200)}
.site-footer a:hover{color:#fff}
.site-footer .cols{display:grid;grid-template-columns:2fr 1fr 1fr;gap:30px}
.site-footer h4{margin:0 0 8px;color:#fff;font-weight:600}

@media (max-width:760px){
  .grid,.trio,.site-footer .cols{grid-template-columns:1fr}
  .head-row{flex-direction:column;align-items:flex-start;gap:12px}
  .brand-logo{height:64px}
  .entry{padding:24px 20px}
  .hero h1{font-size:1.7rem}
}
